def apply_transformation(input_grid):
    output_grid = [row[:] for row in input_grid]
    h, w = len(input_grid), len(input_grid[0])

    l_color = 2
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == l_color:
                up = all(input_grid[r-dr][c] == l_color for i, dr in enumerate(range(1, r+1)))
                left = all(input_grid[r][c-dc] == l_color for i, dc in enumerate(range(1, c+1)))
                if up and left:
                    if all(input_grid[i][c] == l_color for i in range(r+1)):
                        if all(input_grid[r][j] == l_color for j in range(c)):
                            corner = (r, c)
                            break

        if corner:
            break

    cr, cc = corner
    new_row = max(0, min(2 * cr, h-1))
    new_count = max(1, cr // 2)

    new_cells = [(new_row, cc)]
    for i in range(1, new_count):
        new_cells.append((new_row + i, cc + (i if i < 2 else 0)))

    for nr, nc in new_cells:
        if nr < h and nc < w and output_grid[nr][nc] == 0:
            output_grid[nr][nc] = l_color

    return output_grid

